import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, IcosahedronGeometry, InstancedMesh } from 'three/webgpu';
import {
    mix,
    uv,
    vec3,
    position,
    time,
    sin,
    multiply,
    add,
    sub,
    divide,
    clamp,
    float,
    negate,
} from 'three/tsl';
import { gsap } from 'gsap';
import { particleEmit } from '@/primitives';
import {} from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {any} [textContent]
 * @property {any} [intent]
 * @property {any} [cinematicPrimitives]
 * @property {any} [gradientStops]
 * @property {any} [colors]
 *
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} videoLoader
 * @property {any} fontAtlas
 * @property {any} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * Create the particle constellation hero node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
    const {
        Group,
        DirectionalLight,
        AmbientLight,
        DoubleSide,
        AdditiveBlending,
        Vector3,
        Matrix4,
    } = ctx.THREE;

    // Root group (position/rotation/scale applied by adapter)
    const root = new Group();

    // ---------- Backdrop Plane ----------
    const planeGeom = new ctx.THREE.PlaneGeometry(7, 6);
    const backdropMat = new MeshBasicNodeMaterial({
        side: DoubleSide,
        color: mix(vec3('#0b0b10'), vec3('#16161d'), uv().y),
        transparent: false,
    });
    const backdrop = new ctx.THREE.Mesh(planeGeom, backdropMat);
    backdrop.position.set(0, 0, -2.5);
    root.add(backdrop);

    // ---------- Lights ----------
    const ambient = new AmbientLight(0xffffff, 0.6);
    root.add(ambient);

    const keyLight = new DirectionalLight(0xffffff, 1.2);
    keyLight.position.set(5, 8, 5);
    root.add(keyLight);

    const rimLight = new DirectionalLight(0xff2a38, 0.8);
    rimLight.position.set(-5, -8, -5);
    root.add(rimLight);

    // ---------- Particle Materials ----------
    // Depth‑falloff node for field particles
    const depthFalloff = (() => {
        const zPos = position().z; // world‑space Z
        const t = clamp(divide(negate(zPos), float(5)), float(0), float(1));
        return mix(float(0.9), float(0.15), t);
    })();

    const fieldMat = new MeshStandardNodeMaterial({
        color: vec3('#e8ecf2'),
        metalness: float(0.0),
        roughness: float(1.0),
        transparent: true,
        opacity: depthFalloff,
    });

    const coreMat = new MeshStandardNodeMaterial({
        color: vec3('#ff2a38'),
        emissive: vec3('#ff2a38'),
        emissiveIntensity: mix(
            float(1.5),
            float(1.8),
            divide(add(sin(multiply(time(), float(0.2 * Math.PI))), float(1.0)), float(2.0))
        ),
        metalness: float(0.0),
        roughness: float(0.5),
        transparent: true,
        blending: AdditiveBlending,
        depthWrite: false,
    });

    // ---------- Instanced Meshes ----------
    const icoGeom = new IcosahedronGeometry(0.012, 0);
    const TOTAL_COUNT = 1200;
    const CORE_COUNT = 90;
    const FIELD_COUNT = TOTAL_COUNT - CORE_COUNT;

    const coreMesh = new InstancedMesh(icoGeom, coreMat, CORE_COUNT);
    const fieldMesh = new InstancedMesh(icoGeom, fieldMat, FIELD_COUNT);
    const coreMatrix = new Matrix4();
    const fieldMatrix = new Matrix4();

    // Core instances within 0.5 radius sphere
    for (let i = 0; i < CORE_COUNT; i++) {
        const phi = Math.random() * Math.PI * 2;
        const costheta = Math.random() * 2 - 1;
        const u = Math.random();
        const theta = Math.acos(costheta);
        const r = 0.5 * Math.cbrt(u);
        const x = r * Math.sin(theta) * Math.cos(phi);
        const y = r * Math.sin(theta) * Math.sin(phi);
        const z = r * Math.cos(theta);
        coreMatrix.makeTranslation(x, y, z);
        coreMesh.setMatrixAt(i, coreMatrix);
    }
    root.add(coreMesh);

    // Field instances distributed in ellipsoidal shell 6×4×5 centered at (0,0,-1.5)
    for (let i = 0; i < FIELD_COUNT; i++) {
        const x = (Math.random() - 0.5) * 6; // width
        const y = (Math.random() - 0.5) * 4; // height
        const z = -1.5 + (Math.random() - 0.5) * 5; // depth
        fieldMatrix.makeTranslation(x, y, z);
        fieldMesh.setMatrixAt(i, fieldMatrix);
    }
    root.add(fieldMesh);

    // ---------- Ambient Drift (orbit around anchor) ----------
    const DRIFT_AMPLITUDE = 0.04;
    const DRIFT_FREQ = 0.05; // Hz

    const driftTicker = gsap.ticker.add((delta) => {
        const now = gsap.ticker.time / 1000;
        const angle = 2 * Math.PI * DRIFT_FREQ * now;

        // Core drift
        for (let i = 0; i < CORE_COUNT; i++) {
            coreMesh.getMatrixAt(i, coreMatrix);
            const pos = new Vector3();
            pos.setFromMatrixPosition(coreMatrix);
            const offsetX = DRIFT_AMPLITUDE * Math.sin(angle + i);
            const offsetY = DRIFT_AMPLITUDE * Math.cos(angle + i);
            coreMatrix.makeTranslation(pos.x + offsetX, pos.y + offsetY, pos.z);
            coreMesh.setMatrixAt(i, coreMatrix);
        }

        // Field drift
        for (let i = 0; i < FIELD_COUNT; i++) {
            fieldMesh.getMatrixAt(i, fieldMatrix);
            const pos = new Vector3();
            pos.setFromMatrixPosition(fieldMatrix);
            const offsetX = DRIFT_AMPLITUDE * Math.sin(angle + i);
            const offsetY = DRIFT_AMPLITUDE * Math.cos(angle + i);
            fieldMatrix.makeTranslation(pos.x + offsetX, pos.y + offsetY, pos.z);
            fieldMesh.setMatrixAt(i, fieldMatrix);
        }

        coreMesh.instanceMatrix.needsUpdate = true;
        fieldMesh.instanceMatrix.needsUpdate = true;
    });

    // ---------- Text ----------
    const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

    const createText = (content, opts) => ctx.fontAtlas.createText(content, opts);

    // Hero
    const hero = createText('NOVA ATELIER', {
        fontSize: 124,
        color: '#e8ecf2',
        align: 'center',
    });
    hero.position.set(0, 0.5, 0.5);
    root.add(hero);

    // Subhead
    const subhead = createText('Precision instruments for the dark hours.', {
        fontSize: 40,
        color: '#e8ecf2',
        align: 'center',
    });
    subhead.position.set(0, -0.25, 0.5);
    root.add(subhead);

    // Caption
    const caption = createText('EST. 2019 / GENEVA AND KYOTO', {
        fontSize: 18,
        color: '#e8ecf2',
        align: 'center',
    });
    caption.position.set(0, -2.25, 0.5);
    root.add(caption);

    // ---------- Cinematic Primitives ----------
    const primitiveInstances = [];
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            const { name, params } = prim;
            if (ctx.primitives[name]) {
                const target = root;
                const result = ctx.primitives[name](target, params);
                if (result && typeof result.cleanup === 'function') {
                    primitiveInstances.push(result);
                }
            }
        }
    }

    // ---------- Cleanup ----------
    root.userData.handlers = {};
    root.userData.cleanup = () => {
        // Dispose materials
        fieldMat.dispose();
        coreMat.dispose();
        backdropMat.dispose();

        // Remove drift ticker
        gsap.ticker.remove(driftTicker);

        // Cleanup primitives
        for (const p of primitiveInstances) {
            if (p && typeof p.cleanup === 'function') p.cleanup();
        }

        // Dispose geometries
        icoGeom.dispose();
        planeGeom.dispose();
    };

    return root;
}
